WITH unpacked AS (SELECT id, service, host, latency_ms, payload_json, COALESCE(context['region'], 'direct') AS region_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs WHERE latency_ms > 1002) SELECT id, service, host, AVG(latency_ms) OVER (PARTITION BY service ORDER BY latency_ms, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS latency_ms_avg_3_prior, AVG(latency_ms) OVER (PARTITION BY host, service ORDER BY latency_ms, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS latency_ms_avg_3_prior_2 FROM unpacked
